package org.traceform.edge;
import org.json.JSONArray;
import org.json.JSONObject;
public final class CrashWindowProbe {
    public static void main(String[] args) throws Exception {
        JSONArray names=new JSONArray(), medians=new JSONArray(), iqrs=new JSONArray(), centers=new JSONArray(), velocity=new JSONArray();
        for(int i=0;i<128;i++){names.put("synthetic_"+i);medians.put(0.0);iqrs.put(1.0);}
        for(int i=0;i<256;i++){centers.put(0.0);velocity.put(0.0);}
        JSONObject core=new JSONObject().put("normalizer_sha256",String.format("%064d",9))
            .put("feature_names",names).put("tokens",new JSONArray().put("A").put("B"))
            .put("medians",medians).put("iqrs",iqrs).put("centers",centers).put("center_velocity",velocity)
            .put("grid_coordinates",new JSONArray().put(new JSONArray().put(0).put(0)).put(new JSONArray().put(0).put(1)))
            .put("kinetic_weight",0.35).put("ema_alpha",0.4);
        ModelEngine model=ModelEngine.fromRegistry(core,String.format("%064d",1),String.format("%064d",7));

        java.io.File root=new java.io.File(args[0]);
        boolean writer=args[1].equals("writer");
        if(writer && !root.mkdir())throw new IllegalStateException("fresh synthetic directory required");
        java.io.File registryPath=new java.io.File(root,"registry"), candidates=new java.io.File(root,"candidates");
        try(android.database.sqlite.SQLiteDatabase history=android.database.sqlite.SQLiteDatabase.openOrCreateDatabase(new java.io.File(root,"history.sqlite"),null)) {
            NativeModelRegistry registry=new NativeModelRegistry(registryPath,model);
            String window="2026-10-04";
            if(writer) {
                ColdTrajectory.initialize(history);
                ColdTrajectory.register(history,model.modelVersion,model.normalizerDigest,model.tokens,model.coldBundle());
                ColdLineage.migrateOnce(history);
                history.execSQL("CREATE TABLE frames (ts INTEGER PRIMARY KEY,payload TEXT)");
                history.execSQL("CREATE TABLE warm_trajectory (bucket INTEGER PRIMARY KEY,ts INTEGER,payload TEXT,n INTEGER)");
                java.lang.reflect.Method report=NativeRegistryFixture.class.getDeclaredMethod("report",ModelEngine.class,String.class);
                report.setAccessible(true);
                String digest=NativeCandidateStore.save(candidates,model,(JSONObject)report.invoke(null,model,String.format("%064d",1)));
                String activated=registry.activateWeeklyWithHistory(candidates,digest,model.modelVersion,history,window);
                System.out.println(new JSONObject().put("stage","published_before_weekly_receipt").put("pid",android.os.Process.myPid())
                    .put("activated_model_version",activated).put("candidate_sha256",digest).put("window",window));
                System.out.flush();
                Thread.sleep(90000);
                throw new IllegalStateException("writer was not terminated at the requested boundary");
            } else {
                JSONObject recovered=registry.completedWeeklyActivation(window);
                if(recovered==null)throw new IllegalStateException("published weekly window missing after process death");
                String activated=recovered.getString("activated_model_version");
                byte[] before=java.nio.file.Files.readAllBytes(new java.io.File(registryPath,"current.json").toPath());
                long count=android.database.DatabaseUtils.queryNumEntries(history,"cold_models");
                if(!activated.equals(registry.active().modelVersion) || count!=2
                    || !activated.equals(registry.activeIfChanged(model.modelVersion,history).modelVersion))
                    throw new IllegalStateException("database admission and pointer mismatch after process death");
                String replay=registry.activateWeeklyWithHistory(candidates,String.format("%064d",999),model.modelVersion,history,window);
                if(!activated.equals(replay) || android.database.DatabaseUtils.queryNumEntries(history,"cold_models")!=count
                    || !java.util.Arrays.equals(before,java.nio.file.Files.readAllBytes(new java.io.File(registryPath,"current.json").toPath()))
                    || new java.io.File(root,"weekly_maintenance.json").exists())
                    throw new IllegalStateException("publication recovery repeated activation or required a weekly receipt");
                System.out.println(new JSONObject().put("passed",true).put("reader_pid",android.os.Process.myPid())
                    .put("published_window_recovered_without_weekly_receipt",true).put("database_admission_verified",true)
                    .put("replay_preserves_pointer_and_model_count",true).put("activated_model_version",activated)
                    .put("scope","synthetic_android_process_SIGKILL_after_publication_not_real_JobService_or_sensor_lifecycle"));
            }
        }
    }
}
